minimum("HF_pabs_fixed","AbsolutePressure",fixed,true);if(!flap.isEmpty())minimum("HF_pabs_flap","AbsolutePressure",flap,true);minimum("HF_pabs_liquid_all","AbsolutePressure",regions,true);
